/**
 * 2D decode support.
 *
 * The scanner now offers QR, Data Matrix and PDF417 alongside the linear
 * formats. These tests prove the claim rather than asserting it: a symbol is
 * generated by bwip-js, turned into real pixels by pngjs, and decoded by the
 * same `decodeFirst` ladder the camera uses. A linear symbol is decoded through
 * the same ladder so the extra reader hints cannot hide a regression.
 */
import { describe, expect, it } from "vitest";
import bwipjs from "bwip-js";
import { PNG } from "pngjs";
import { buildBarcode } from "@/lib/tools/barcode/encode";
import { buildLayout } from "@/lib/tools/barcode/layout";
import { rasterizeLayout } from "@/lib/tools/barcode/raster";
import {
  decodeBarcodes,
  FORMAT_LABELS,
  READABLE_FORMATS,
} from "@/lib/tools/barcode/decode";

/** Generate a 2D symbol and return the RGBA raster the decoder expects. */
async function rasterFor(bcid: string, text: string) {
  const bytes = (await bwipjs.toBuffer({
    bcid,
    text,
    scale: 4,
    padding: 8,
  })) as Buffer;
  const png = PNG.sync.read(bytes);
  // bwip-js writes a transparent background. A camera never sees transparency,
  // so composite the symbol onto white before it reaches the decoder — a
  // transparent field counts as black once alpha is dropped.
  const rgba = new Uint8ClampedArray(png.data.length);
  for (let index = 0; index < png.data.length; index += 4) {
    const alpha = png.data[index + 3] / 255;
    for (let channel = 0; channel < 3; channel += 1) {
      rgba[index + channel] = Math.round(
        png.data[index + channel] * alpha + 255 * (1 - alpha),
      );
    }
    rgba[index + 3] = 255;
  }
  return { width: png.width, height: png.height, rgba };
}

describe("2D decoding", () => {
  it("lists the three 2D symbologies with human labels", () => {
    expect(READABLE_FORMATS).toEqual(
      expect.arrayContaining(["qrcode", "datamatrix", "pdf417"]),
    );
    expect(FORMAT_LABELS.qrcode).toBe("QR Code");
    expect(FORMAT_LABELS.datamatrix).toBe("Data Matrix");
    expect(FORMAT_LABELS.pdf417).toBe("PDF417");
  });

  it("decodes a QR code and reports the format", async () => {
    const outcome = decodeBarcodes(
      await rasterFor("qrcode", "https://quickkit.online"),
      { profile: "image" },
    );
    const first = outcome.barcodes[0];
    expect(first?.format).toBe("qrcode");
    expect(first?.label).toBe("QR Code");
    expect(first?.text).toBe("https://quickkit.online");
  });

  it("decodes a Data Matrix symbol", async () => {
    const outcome = decodeBarcodes(
      await rasterFor("datamatrix", "QUICKKIT-DM-0001"),
      { profile: "image" },
    );
    const found = outcome.barcodes.find(
      (entry) => entry.format === "datamatrix",
    );
    expect(found?.text).toBe("QUICKKIT-DM-0001");
  });

  it("decodes a PDF417 symbol", async () => {
    const outcome = decodeBarcodes(
      await rasterFor("pdf417", "QUICKKIT-PDF417-0001"),
      { profile: "image" },
    );
    const found = outcome.barcodes.find((entry) => entry.format === "pdf417");
    expect(found?.text).toBe("QUICKKIT-PDF417-0001");
  });

  it("still decodes a linear symbol with the 2D readers enabled", () => {
    const built = buildBarcode("code128", "QUICKKIT-LINEAR-0001", {});
    if (!built.ok) throw new Error("Code 128 fixture failed to encode");
    const layout = buildLayout({
      spec: built.spec,
      options: { moduleWidth: 3 },
    });
    const raster = rasterizeLayout(layout, { scale: 2 });
    const outcome = decodeBarcodes(raster, { profile: "image" });
    const found = outcome.barcodes.find((entry) => entry.format === "code128");
    expect(found?.text).toBe("QUICKKIT-LINEAR-0001");
  });
});
